-- Reloads the Kajkavian seed words from the reviewed table. The captain's decisions: every word is used in
-- Sveti Petar Orehovec, active words are approved (status verified), ids are UUIDs, and the old seeded and
-- sample rows (text ids such as hiza, babica) are removed first. Nobody uses the app yet, so links to old rows are dropped.
--
-- Scope of the delete: exactly the 61 ids created by 20261028010000_heritage_words.sql and
-- 20261101010000_seed_kajkavian_words.sql, and only while submission_id is null. Any other heritage_words row,
-- and any row linked to a submission, is left alone.
-- References to those ids: heritage_daily_words.word_id is a foreign key, so its rows go first. Resolved days are
-- protected by heritage_daily_word_guard (no delete), so the trigger is disabled just for that statement inside this
-- transaction. replaced_word_ids is a plain text[] without a foreign key and needs no change. Challenges
-- (heritage_challenges.content) and submissions (target_ref is an atlas item id) hold no foreign keys to words.
-- The inserts use on conflict do nothing, so replaying the file never overwrites a later edit.
-- The 10 words the review marked inactive keep their corrected data but stay hidden (active = false, status placeholder).
-- Categories are proposals for review; example, note and distractors are intentionally left empty.
begin;

alter table public.heritage_daily_words disable trigger heritage_daily_word_guard;
delete from public.heritage_daily_words where word_id in (
  select id from public.heritage_words where submission_id is null and id = any (array[
    'afinger',
    'ajncug',
    'alto',
    'ambriela',
    'andel',
